mapper.select:
select bo.organization_id, bo.parent_organization_id, bo.level, bo.tenant_id, bo.name, bo.sort,
bo.status, DATE_FORMAT(bo.create_time, '%Y-%m-%d %H:%i:%s') as create_time
from b_organization bo
where bo.flag = 1


    bo.tenant_id = #{param.tenantId}



    bo.parent_organization_id = #{param.parent_organization_id}




    and block.name like #{name}


order by bo.sort asc
